package com.bank.recon;

import java.util.List;

// The result of cogroup for ONE key: the key plus both full value lists.
// Mirrors Spark's (key, (Iterable[V1], Iterable[V2])).
class CoGrouped {
    final String accountId;
    final List<Movement> deposits;     // all deposits for this account (may be empty)
    final List<Movement> withdrawals;  // all withdrawals for this account (may be empty)

    CoGrouped(String accountId, List<Movement> deposits, List<Movement> withdrawals) {
        this.accountId = accountId;
        this.deposits = deposits;
        this.withdrawals = withdrawals;
    }
}
