package com.bank.recon;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.TreeSet;
import java.util.logging.Logger;

// Simulates RDD.cogroup: group both sides by key, emit per-key pair of value lists.
class CoGrouper {
    private static final Logger log = Logger.getLogger(CoGrouper.class.getName());

    List<CoGrouped> cogroup(List<Movement> deposits, List<Movement> withdrawals) {
        // Group each side by account id (the shuffle-and-group step).
        Map<String, List<Movement>> depByAcct = groupByAccount(deposits);
        Map<String, List<Movement>> wdByAcct = groupByAccount(withdrawals);

        // Union of keys from BOTH sides — this gives full-outer behavior.
        TreeSet<String> allAccounts = new TreeSet<>();
        allAccounts.addAll(depByAcct.keySet());
        allAccounts.addAll(wdByAcct.keySet());

        List<CoGrouped> result = new ArrayList<>();
        for (String acct : allAccounts) {
            List<Movement> d = depByAcct.getOrDefault(acct, new ArrayList<>());
            List<Movement> w = wdByAcct.getOrDefault(acct, new ArrayList<>());
            result.add(new CoGrouped(acct, d, w));
            log.fine(() -> "cogroup key=" + acct + " deposits=" + d.size() + " withdrawals=" + w.size());
        }
        log.info(() -> "cogroup produced " + result.size() + " keys (union of both sides)");
        return result;
    }

    private Map<String, List<Movement>> groupByAccount(List<Movement> movements) {
        Map<String, List<Movement>> grouped = new TreeMap<>();
        for (Movement m : movements) {
            grouped.computeIfAbsent(m.accountId, k -> new ArrayList<>()).add(m);
        }
        return grouped;
    }
}
