package com.bank.recon;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.Logger;

// Consumes cogroup output to compute net flow and flag overdrawn accounts.
class ReconciliationService {
    private static final Logger log = Logger.getLogger(ReconciliationService.class.getName());

    void reconcile(List<CoGrouped> cogrouped) {
        for (CoGrouped cg : cogrouped) {
            BigDecimal depositTotal = sum(cg.deposits);
            BigDecimal withdrawalTotal = sum(cg.withdrawals);
            BigDecimal net = depositTotal.subtract(withdrawalTotal);

            if (net.signum() < 0) {
                log.warning(() -> "OVERDRAWN " + cg.accountId + " deposits=Rs." + depositTotal
                        + " withdrawals=Rs." + withdrawalTotal + " net=Rs." + net);
            } else {
                log.info(() -> "OK " + cg.accountId + " deposits=Rs." + depositTotal
                        + " withdrawals=Rs." + withdrawalTotal + " net=Rs." + net);
            }
        }
    }

    private BigDecimal sum(List<Movement> movements) {
        return movements.stream().map(m -> m.amount).reduce(BigDecimal.ZERO, BigDecimal::add);
    }
}
