package com.bank.recon;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.Logger;

// Shows the WRONG approach: an inner join pairs every deposit with every withdrawal,
// multiplying values and dropping single-sided accounts.
class NaiveJoiner {
    private static final Logger log = Logger.getLogger(NaiveJoiner.class.getName());

    void joinAndSum(List<Movement> deposits, List<Movement> withdrawals) {
        // Pairwise combinations per key — Cartesian explosion.
        for (Movement d : deposits) {
            for (Movement w : withdrawals) {
                if (d.accountId.equals(w.accountId)) {
                    BigDecimal pairNet = d.amount.subtract(w.amount);
                    log.fine(() -> "join pair " + d.accountId + " dep=" + d.amount
                            + " wd=" + w.amount + " pairNet=" + pairNet + " (counted multiple times!)");
                }
            }
        }
        log.warning("Join produced pairwise rows — totals computed from these are WRONG and drop single-sided accounts");
    }
}
