package com.bank.recon;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.Logger;

public class CoGroupDemo {
    private static final Logger log = Logger.getLogger(CoGroupDemo.class.getName());

    public static void main(String[] args) {
        // Rajesh (SAV2001): 3 deposits, 1 withdrawal.
        // Priya (CUR3001): 0 deposits, 2 withdrawals (withdrawal-only — join would drop her).
        List<Movement> deposits = List.of(
            new Movement("SAV2001", new BigDecimal("40000")),
            new Movement("SAV2001", new BigDecimal("30000")),
            new Movement("SAV2001", new BigDecimal("20000"))
        );
        List<Movement> withdrawals = List.of(
            new Movement("SAV2001", new BigDecimal("50000")),
            new Movement("CUR3001", new BigDecimal("80000")),
            new Movement("CUR3001", new BigDecimal("30000"))
        );

        log.info("=== Naive join approach (WRONG) ===");
        new NaiveJoiner().joinAndSum(deposits, withdrawals);

        log.info("=== cogroup approach (CORRECT) ===");
        List<CoGrouped> cg = new CoGrouper().cogroup(deposits, withdrawals);
        new ReconciliationService().reconcile(cg);
    }
}
